import { readFileSync } from 'node:fs';
import { expect, sample, test, uniqueName } from '../../fixtures';

test('extraction completes in the background', { tag: '@DOC-02' }, async ({ apiAs }) => {
  const member = await apiAs('member');

  const vendorRes = await member.post('/api/vendors', {
    data: { name: uniqueName('DOC-02 Vendor'), category: 'services', contact_email: 'ops@doc02.example.com' },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = await vendorRes.json();
  expect(vendor.status, JSON.stringify(vendor)).toBe('draft');

  const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: 'insurance_certificate',
      file: {
        name: 'insurance_certificate.txt',
        mimeType: 'text/plain',
        buffer: readFileSync(sample('insurance_certificate.txt')),
      },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);
  const doc = await upload.json();
  expect(doc.kind, JSON.stringify(doc)).toBe('insurance_certificate');

  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/documents/${doc.id}`);
        const body = await res.json();
        return body.status;
      },
      { timeout: 60_000, message: 'document should leave processing' },
    )
    .toBe('extracted');

  const exRes = await member.get(`/api/documents/${doc.id}/extraction`);
  expect(exRes.status(), await exRes.text()).toBe(200);
  const extraction = await exRes.json();
  const body = JSON.stringify(extraction);

  for (const field of ['insurer', 'policy_number', 'coverage_amount', 'expiry_date']) {
    expect(Object.keys(extraction.fields), body).toContain(field);
  }

  for (const [name, field] of Object.entries(extraction.fields as Record<string, { confidence: unknown }>)) {
    expect(typeof field.confidence, `${name} in ${body}`).toBe('number');
    expect(field.confidence as number, `${name} in ${body}`).toBeGreaterThanOrEqual(0);
    expect(field.confidence as number, `${name} in ${body}`).toBeLessThanOrEqual(1);
  }
});
